<template><section><div class="page-heading"><div><p class="eyebrow">نظرة عامة</p><h1>لوحة التحكم</h1></div><span class="date">اليوم</span></div><div class="stats"><div v-for="s in stats" :key="s.label" class="stat-card"><span>{{ s.icon }}</span><small>{{ s.label }}</small><strong>{{ s.value }}</strong></div></div><div class="panel"><div class="panel-title"><h2>تنبيهات المخزون</h2><RouterLink to="/products">عرض الكل ←</RouterLink></div><p v-if="!low.length" class="empty">لا توجد تنبيهات حالياً</p><div v-for="p in low" :key="p._id" class="alert-row"><span>⚠️</span><strong>{{ p.name_ar }}</strong><small>المتوفر {{ p.stock }} — الحد الأدنى {{ p.min_stock }}</small></div></div></section></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import db,{type Product,type Sale} from '../services/pouchdb';const stats=ref([{icon:'💰',label:'مبيعات اليوم',value:'0'},{icon:'📈',label:'الأرباح التقديرية',value:'0'},{icon:'📦',label:'المنتجات الناقصة',value:'0'},{icon:'🧾',label:'الفواتير',value:'0'}]);const low=ref<Product[]>([]);onMounted(async()=>{const ps=await db.list<Product>('product');low.value=ps.filter(p=>p.stock<=p.min_stock);const sales=await db.list<Sale>('sale');const today=sales.filter(s=>s.created_at.slice(0,10)===new Date().toISOString().slice(0,10));stats.value[0].value=String(today.reduce((n,s)=>n+s.total,0));stats.value[2].value=String(low.value.length);stats.value[3].value=String(today.length)})</script>
